% --- FUNCIONES ASTRONÓMICAS CORE ---% Conversiones básicasfunction rad = deg2rad(deg)    rad = deg * pi / 180;endfunction deg = rad2deg(rad)    deg = rad * 180 / pi;endfunction hms = deg2hms(grados)    % Convertir grados a horas, minutos, segundos    horas = grados / 15;    h = floor(horas);    m = floor((horas - h) * 60);    s = ((horas - h) * 60 - m) * 60;    hms = [h, m, s];end% Sistema Alt/Az -> Horario/Decfunction [ha, dec] = altaz2hadec(alt, az, lat)    alt_rad = deg2rad(alt);    az_rad = deg2rad(az);    lat_rad = deg2rad(lat);        dec_rad = asin(sin(alt_rad) * sin(lat_rad) + ...                   cos(alt_rad) * cos(lat_rad) * cos(az_rad));    ha_rad = atan2(-sin(az_rad) * cos(alt_rad), ...                   -cos(az_rad) * sin(lat_rad) * cos(alt_rad) + ...                   sin(alt_rad) * cos(lat_rad));        ha = rad2deg(ha_rad);    dec = rad2deg(dec_rad);end% Sistema Horario/Dec -> Ecuatorial (RA/Dec)function [ra, dec] = hadec2radec(ha, dec_hadec, lst)    % ha en grados, lst en horas    ra = mod(lst - ha/15, 24);    dec = dec_hadec;end% Tiempo Sidéreo Localfunction lst = calcular_lst(fecha, longitud)    % fecha: número serial de fecha (datenum)    % longitud: en grados (Este positivo)        jd = fecha + 2415018.5;  % Fecha Juliana aproximada        t = (jd - 2451545.0) / 36525.0;        % Tiempo sidéreo en Greenwich (grados)    gmst = 280.46061837 + 360.98564736629 * (jd - 2451545.0) + ...           0.000387933 * t.*t - t.*t.*t / 38710000.0;        % Ajustar a longitud local y convertir a horas    lst = mod(gmst + longitud, 360) / 15;end